    32  static void
    33  each_backtrace(mrb_state *mrb, ptrdiff_t ciidx, each_backtrace_func func, void *data)
    34  {
    35    if (ciidx >= mrb->c->ciend - mrb->c->cibase)
    36      ciidx = 10; /* ciidx is broken... */
    37
    38    for (ptrdiff_t i=ciidx; i >= 0; i--) {
    39      struct backtrace_location loc;
    40      mrb_callinfo *ci;
    41      const mrb_irep *irep = 0;
    42      const mrb_code *pc;
    43      uint32_t idx;
    44
    45      ci = &mrb->c->cibase[i];
    46
    47      if (!ci->proc || MRB_PROC_CFUNC_P(ci->proc)) {
    48        if (!ci->mid) continue;
    49        loc.lineno = -1;
    50        idx = 0;
    51      }
    52      else {
    53        irep = ci->proc->body.irep;
    54        if (!irep) continue;
    55        if (mrb->c->cibase[i].pc) {
    56          pc = &mrb->c->cibase[i].pc[-1];
    57        }
    58        else {
    59          continue;
    60        }
    61        idx = (uint32_t)(pc - irep->iseq);
    62        mrb_debug_get_position(mrb, irep, idx, &loc.lineno, &loc.filename);
    63      }
    64      loc.method_id = ci->mid;
    65      if (loc.lineno == -1) {
    66        for (ptrdiff_t j=i-1; j >= 0; j--) {
    67          ci = &mrb->c->cibase[j];
    68
    69          if (!ci->proc) continue;
    70          if (MRB_PROC_CFUNC_P(ci->proc)) continue;
    71
    72          irep = ci->proc->body.irep;
    73          if (!irep) continue;
    74
    75          if (mrb->c->cibase[j].pc) {
    76            pc = &mrb->c->cibase[j].pc[-1];
    77          }
    78          else {
    79            continue;
    80          }
    81
    82          idx = (uint32_t)(pc - irep->iseq);
    83          if (mrb_debug_get_position(mrb, irep, idx, &loc.lineno, &loc.filename)) break;
    84        }
    85      }
    86      if (!loc.filename) {
    87        loc.filename = "(unknown)";
    88      }
    89
    90      func(mrb, &loc, data);
    91    }
    92  }
