   220  struct RObject*
   221  mrb_unpack_backtrace(mrb_state *mrb, struct RObject *backtrace)
   222  {
   223    const struct backtrace_location *bt;
   224    mrb_int n, i;
   225    int ai;
   226
   227    if (backtrace == NULL) {
   228    empty_backtrace:
   229      return mrb_obj_ptr(mrb_ary_new_capa(mrb, 0));
   230    }
   231    if (backtrace->tt == MRB_TT_ARRAY) return backtrace;
   232    bt = (struct backtrace_location*)mrb_data_check_get_ptr(mrb, mrb_obj_value(backtrace), &bt_type);
   233    if (bt == NULL) goto empty_backtrace;
   234    n = (mrb_int)backtrace->flags;
   235    if (n == 0) goto empty_backtrace;
   236    backtrace = mrb_obj_ptr(mrb_ary_new_capa(mrb, n));
   237    ai = mrb_gc_arena_save(mrb);
   238    for (i = 0; i < n; i++) {
   239      const struct backtrace_location *entry = &bt[i];
   240      mrb_value btline;
   241
   242      if (entry->lineno != -1) {//debug info was available
   243        btline = mrb_format(mrb, "%s:%d", entry->filename, (int)entry->lineno);
   244      }
   245      else { //all that was left was the stack frame
   246        btline = mrb_format(mrb, "%s:0", entry->filename);
   247      }
   248      if (entry->method_id != 0) {
   249        mrb_str_cat_lit(mrb, btline, ":in ");
   250        mrb_str_cat_cstr(mrb, btline, mrb_sym_name(mrb, entry->method_id));
   251      }
   252      mrb_ary_push(mrb, mrb_obj_value(backtrace), btline);
   253      mrb_gc_arena_restore(mrb, ai);
   254    }
   255
   256    return backtrace;
   257  }
